const hotnessList = await browserjs(tabId, () => {
  const main = document.querySelector('main');
  // Find all items in the list under main
  const items = Array.from(main.querySelectorAll('li'));
  const results = [];

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const link = item.querySelector('h2 a') || item.querySelector('a[href*="/boardgame/"]');
    if (!link) continue;
    const href = link.getAttribute('href');
    if (!href || !href.includes('/boardgame/')) continue;

    // Extract game ID from href: /boardgame/12345/name
    const match = href.match(/\/boardgame\/(\d+)/);
    const id = match ? match[1] : null;

    results.push({
      rank: results.length + 1,
      title: link.textContent.trim(),
      href: link.href,
      id: id,
      text: item.textContent.replace(/\s+/g, ' ').trim()
    });
  }
  return results;
});

