      if (startIndex === -1) continue;
      const jsonStart = startIndex + startMarker.length;
      const endMarker = ';\n\tGEEK.geekitemSettings';
      const endIndex = html.indexOf(endMarker, jsonStart);
      if (endIndex === -1) continue;

      const jsonStr = html.slice(jsonStart, endIndex);
      const data = JSON.parse(jsonStr);
      const gItem = data.item;

      results.push({
        rank: i + 1,
        name: gItem.name,
        year: gItem.yearpublished,
        avgRating: gItem.stats?.average ? Number(parseFloat(gItem.stats.average).toFixed(2)) : null,
        geekRating: gItem.stats?.baverage ? Number(parseFloat(gItem.stats.baverage).toFixed(2)) : null,
        usersRated: parseInt(gItem.stats?.usersrated || '0'),
        minplayers: parseInt(gItem.minplayers || '0'),
        maxplayers: parseInt(gItem.maxplayers || '0')
      });
    } catch(e) {
      // ignore
    }
  }
  return results;
});

