const tabId = 1962625075;

const pageState = await browserjs(tabId, () => {
  // Let's check ratings and player info
  const ratingEl = document.querySelector('.rating-container, [class*="rating"], ng-component');
  // Look for any elements containing rating values like 7.x
  const elements = Array.from(document.querySelectorAll('*'));
  const ratings = [];
  for (const el of elements) {
    if (el.children.length === 0 && el.textContent) {
      const match = el.textContent.trim().match(/^([0-9]\.[0-9]+)$/);
      if (match) {
        ratings.push({ tag: el.tagName, className: el.className, val: match[1], parent: el.parentElement?.textContent?.replace(/\s+/g, ' ').trim() });
      }
    }
  }

  // Also check player count info
  const playerInfo = Array.from(document.querySelectorAll('*')).filter(el => el.textContent && el.textContent.includes('Number of Players') && el.children.length < 5).map(el => el.textContent.replace(/\s+/g, ' ').trim());

  return {
    ratings,
    playerInfo
  };
});

console.log(JSON.stringify(pageState, null, 2));

