const tabId = 1962625075;
const todoPath = "tmp://sessions/channel%3Apanel%3A60f36bd2-efcb-470a-8d17-68a866d5bfc9/TODO.md";

await edit({
  path: todoPath,
  edits: [{
    oldText: "- [ ] Inspect games in order of popularity (top to bottom on The Hotness list)",
    newText: "- [/] Inspect games in order of popularity (top to bottom on The Hotness list)"
  }]
});

const gameResults = await browserjs(tabId, async () => {
  const hotRes = await fetch('/api/hotness');
  const hotJson = await hotRes.json();
  const items = hotJson.items;

  const results = [];

  for (let i = 0; i < Math.min(items.length, 25); i++) {
    const item = items[i];
    try {
      const res = await fetch(item.href);
      const html = await res.text();
      const startMarker = 'GEEK.geekitemPreload = ';
      const startIndex = html.indexOf(startMarker);
      if (startIndex === -1) {
        results.push({ rank: i + 1, name: item.name, href: item.href, error: "no preload" });
        continue;
      }
      const jsonStart = startIndex + startMarker.length;
      const endMarker = ';\n\tGEEK.geekitemSettings';
      const endIndex = html.indexOf(endMarker, jsonStart);
      if (endIndex === -1) {
        results.push({ rank: i + 1, name: item.name, href: item.href, error: "no end marker" });
        continue;
      }
      const jsonStr = html.slice(jsonStart, endIndex);
      const data = JSON.parse(jsonStr);
      const gItem = data.item;
      const avgRating = gItem.stats?.average ? parseFloat(gItem.stats.average) : null;
      const usersRated = gItem.stats?.usersrated ? parseInt(gItem.stats.usersrated) : 0;
      const minp = gItem.minplayers ? parseInt(gItem.minplayers) : null;
      const maxp = gItem.maxplayers ? parseInt(gItem.maxplayers) : null;
      const userPlayersPoll = gItem.polls?.userplayers;

      results.push({
        rank: i + 1,
        name: gItem.name,
        year: gItem.yearpublished,
        avgRating,
        usersRated,
        minplayers: minp,
        maxplayers: maxp,
        userPlayersPoll,
        href: item.href
      });
    } catch(e) {
      results.push({ rank: i + 1, name: item.name, href: item.href, error: e.message });
    }
  }
  return results;
});

console.log(JSON.stringify(gameResults, null, 2));

