const visibleDetails = await browserjs(tabId, () => {
  // Let's find all text in the main content area of the game
  const headerContent = document.querySelector('.game-header-body') || document.querySelector('.header-body') || document.querySelector('ng-component');

  // Find player count text
  const playersEl = Array.from(document.querySelectorAll('*')).find(el => el.textContent && el.textContent.includes('Number of Players') && el.children.length < 5);

  // Find rating elements
  const ratingEls = Array.from(document.querySelectorAll('.game-rating, .rating-container, [class*="rating"]'));

  return {
    playersText: playersEl ? playersEl.textContent.replace(/\s+/g, ' ').trim() : null,
    ratingEls: ratingEls.map(el => el.textContent.replace(/\s+/g, ' ').trim()).filter(Boolean)
  };
});

